package com.suhas.nsedeliverymomentum;
/** Intraday target calculator. Targets are first model objectives, not guarantees. */
public final class TargetMath {
    private TargetMath(){}
    static double continuationPct(double expectedRemaining,double confidence){double confidenceScale=0.85+0.15*clamp(confidence/100.0,0,1);return clamp(Math.max(1.0,expectedRemaining*confidenceScale),1.0,4.0);}
    static double trajectoryPct(double hourlyPace,double recentPace,double confidence){double pace=Math.max(0,0.45*Math.max(0,recentPace)+0.35*Math.max(0,hourlyPace));double conf=0.40*clamp(confidence/100.0,0,1);return clamp(Math.max(1.0,pace+conf),1.0,3.0);}
    static double shortPct(double recentDrop,double hourlyPace,double recentPace,double freshBreakdown,double confidence){double momentum=0.45*Math.max(0,recentDrop)+0.25*Math.max(0,-recentPace)+0.15*Math.max(0,-hourlyPace)+0.15*Math.max(0,freshBreakdown);double conf=0.35*clamp(confidence/100.0,0,1);return clamp(Math.max(1.0,momentum+conf),1.0,3.5);}
    static double longTarget(double entry,double pct){return round2(entry*(1.0+pct/100.0));}
    static double shortTarget(double entry,double pct){return round2(entry*(1.0-pct/100.0));}
    private static double clamp(double x,double lo,double hi){return Math.max(lo,Math.min(hi,x));}
    private static double round2(double x){return Math.round(x*100.0)/100.0;}
}
