package com.suhas.nsedeliverymomentum;
import org.junit.Test;import static org.junit.Assert.*;
public class TargetMathTest {
 @Test public void longTargetIsAboveEntry(){double p=TargetMath.continuationPct(1.8,85);assertTrue(p>=1);assertTrue(TargetMath.longTarget(100,p)>100);}
 @Test public void shortTargetIsBelowEntry(){double p=TargetMath.shortPct(0.8,-1.0,-1.3,0.2,86);assertTrue(p>=1);assertTrue(TargetMath.shortTarget(100,p)<100);}
 @Test public void exampleDirectionIsCorrect(){assertEquals(110.0,TargetMath.longTarget(100,10),0.001);assertEquals(90.0,TargetMath.shortTarget(100,10),0.001);}
}
